// Conceptual ordering -- not literal Spring Security API, but representative
// of the responsibilities each stage of the chain has, in sequence:
//
// 1. SecurityContextPersistenceFilter / SecurityContextHolderFilter
//      -- restores any existing SecurityContext for this request
// 2. UsernamePasswordAuthenticationFilter (form login) or
//    BasicAuthenticationFilter (HTTP Basic) or a JWT-parsing filter
//      -- extracts credentials from the request and attempts authentication
// 3. AuthorizationFilter
//      -- checks whether the resulting Authentication (or lack of one) is
//         permitted to access this specific URL and HTTP method
// 4. ExceptionTranslationFilter
//      -- catches AuthenticationException / AccessDeniedException thrown by
//         any earlier filter and converts it into 401 / 403 respectively
//
// -- only after ALL of the above succeed does the request ever reach:
//
// 5. DispatcherServlet -> HandlerMapping -> your @RestController method

@RestController
@RequestMapping("/api/account")
public class AccountController {

    @GetMapping("/me")
    public Map<String, Object> currentUser(Authentication authentication) {
        return Map.of(
                "username", authentication.getName(),
                "authorities", authentication.getAuthorities()
        );
    }

    @GetMapping("/me-alternative")
    public String currentUserName(Principal principal) {
        // Equivalent, narrower view -- just the identity, no authorities
        return principal.getName();
    }
}

