@Configuration
@EnableMethodSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http.authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .requestMatchers(HttpMethod.GET, "/api/orders/**").hasAnyRole("CUSTOMER", "ADMIN")
                .anyRequest().authenticated()
        );
        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}

@Service
public class RefundService {

    @PreAuthorize("hasRole('ADMIN')")
    public void issueRefund(Long orderId, BigDecimal amount) {
        // ... process the refund ...
    }
}

@Component
public class NightlyRefundBatchJob {

    private final RefundService refundService;

    public NightlyRefundBatchJob(RefundService refundService) {
        this.refundService = refundService;
    }

    @Scheduled(cron = "0 0 2 * * *")
    public void run() {
        // If this scheduled job's own execution context isn't running as
        // an authenticated ADMIN-role principal, this call is rejected --
        // exactly the same as if it had come from an HTTP request.
        refundService.issueRefund(123L, new BigDecimal("49.99"));
    }
}

// BROKEN: anyRequest() is declared first, so it matches EVERY request,
// including ones meant to hit the /api/public/** rule below it --
// that second rule is now completely unreachable.
http.authorizeHttpRequests(auth -> auth
        .anyRequest().authenticated()
        .requestMatchers("/api/public/**").permitAll()
);

// FIXED: the specific rule is declared first, so it gets first refusal
// on any request matching /api/public/**, before the catch-all applies
// to everything else.
http.authorizeHttpRequests(auth -> auth
        .requestMatchers("/api/public/**").permitAll()
        .anyRequest().authenticated()
);

