@Configuration
public class SecurityConfig {

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}

@Service
public class RegistrationService {

    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;

    public RegistrationService(UserRepository userRepository, PasswordEncoder passwordEncoder) {
        this.userRepository = userRepository;
        this.passwordEncoder = passwordEncoder;
    }

    public void register(String username, String rawPassword) {
        String hashedPassword = passwordEncoder.encode(rawPassword);
        userRepository.save(new User(username, hashedPassword));
        // rawPassword is never persisted anywhere -- only hashedPassword is
    }
}

@Service
public class LoginService {

    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;

    public LoginService(UserRepository userRepository, PasswordEncoder passwordEncoder) {
        this.userRepository = userRepository;
        this.passwordEncoder = passwordEncoder;
    }

    public boolean login(String username, String rawPassword) {
        User user = userRepository.findByUsername(username)
                .orElseThrow(() -> new BadCredentialsException("Invalid username or password"));

        // CORRECT: matches() extracts the salt embedded in the stored hash
        // and re-hashes the candidate password with that SAME salt.
        return passwordEncoder.matches(rawPassword, user.getHashedPassword());

        // WRONG -- do not do this:
        // return user.getHashedPassword().equals(passwordEncoder.encode(rawPassword));
        // encode() generates a NEW random salt every single time it's called,
        // so this comparison would fail even for the objectively correct
        // password, virtually every time.
    }
}

PasswordEncoder encoder = new BCryptPasswordEncoder();

String hash1 = encoder.encode("password123");
String hash2 = encoder.encode("password123");

System.out.println(hash1);
// e.g. $2a$10$EIXo9m3D9nT5cH8kR2b9re...
System.out.println(hash2);
// e.g. $2a$10$9Fj0kNq1QeYVgm4XoP8Cru...  -- completely different string!

System.out.println(hash1.equals(hash2));            // false
System.out.println(encoder.matches("password123", hash1));  // true
System.out.println(encoder.matches("password123", hash2));  // true

